S.append(TITLE('TIN HỌC · ĐẠO ĐỨC VÀ PHÁP LUẬT 2','ĐẠO ĐỨC, PHÁP LUẬT<br>VÀ BẢN QUYỀN','Quy tắc ứng xử trên mạng, văn hoá số, quyền riêng tư, bản quyền, giấy phép phần mềm, pháp luật về an ninh mạng.',['văn hoá số','bản quyền','giấy phép','riêng tư','pháp luật']))
S.append(goals(c,B,['Nêu <b>quy tắc ứng xử</b> có văn hoá trên mạng.','Giải thích <b>quyền riêng tư</b> và bảo vệ dữ liệu cá nhân.','Phân biệt các loại <b>giấy phép phần mềm, nội dung</b> (bản quyền, mã nguồn mở, Creative Commons).','Nhận biết <b>hành vi vi phạm</b> pháp luật trên mạng.','Vận dụng vào <b>tình huống</b> thực tế.'],['Ứng xử trên mạng','Riêng tư','Bản quyền, giấy phép','Pháp luật','Tình huống, HSG']))
