S.append(TB(c,B+' · 1','Hành vi không nên làm trên mạng',['Hành vi','Hậu quả'],[['<b>Bắt nạt trên mạng</b> (cyberbullying)','gây tổn thương tâm lí; có thể bị xử lí kỉ luật, pháp luật'],['<b>Tung tin giả</b>, tin chưa kiểm chứng','gây hoang mang, thiệt hại cho cá nhân, tổ chức'],['Đăng ảnh, thông tin người khác <b>không xin phép</b>','xâm phạm quyền riêng tư'],['Dùng tài khoản người khác','vi phạm pháp luật'],['Phát tán nội dung bạo lực, đồi truỵ','vi phạm quy định, gây hại trẻ em']],note=KEY('Gặp bắt nạt: <b>không đáp trả</b>, lưu bằng chứng, <b>chặn</b>, báo cho thầy cô, phụ huynh, nền tảng.')))
S.append(S2(c,B+' · 1','Thông tin và tin giả',card('Kiểm chứng thông tin',ul(['Xem <b>nguồn</b> đăng và <b>thời gian</b>.','<b>Đối chiếu</b> nhiều nguồn tin cậy.','Cảnh giác tiêu đề giật gân, ảnh cũ ghép tin mới.','Tìm kiếm ngược ảnh.'],6)),KEY('Trước khi chia sẻ: dừng lại, hỏi “<b>Nguồn nào? Có bằng chứng không? Có gây hại không?</b>”.')+WARN('Chia sẻ tin giả có thể <b>bị xử phạt</b> theo quy định pháp luật.')))
S.append(S2(c,B+' · 2','Quyền riêng tư và dữ liệu cá nhân',card('Dữ liệu cá nhân',ul(['Họ tên, ngày sinh, số điện thoại, địa chỉ, <b>số căn cước</b>.','Dữ liệu <b>nhạy cảm</b>: sức khoẻ, tài chính, vị trí.','Mỗi người có quyền <b>biết, đồng ý, rút lại, xoá</b> dữ liệu của mình.'],6)),KEY('Pháp luật Việt Nam bảo vệ dữ liệu cá nhân (Luật Bảo vệ dữ liệu cá nhân; Nghị định 13/2023/NĐ-CP).')))
S.append(TB(c,B+' · 2','Bảo vệ thông tin cá nhân trên mạng',['Nên','Không nên'],[['Đặt chế độ riêng tư cho mạng xã hội','đăng địa chỉ nhà, lịch đi lại'],['Chia sẻ thông tin <b>vừa đủ</b>','đưa số căn cước, thẻ ngân hàng cho người lạ'],['Mật khẩu mạnh, bật 2FA','dùng chung một mật khẩu'],['Đọc <b>điều khoản</b> trước khi đồng ý','nhấn “Đồng ý” mọi quyền ứng dụng yêu cầu'],['Báo ngay khi nghi lộ thông tin','bỏ qua cảnh báo bảo mật']],note=KEY('Dấu chân số (digital footprint): mọi hoạt động trực tuyến để lại dấu vết.')))
S.append(S2(c,B+' · 2','Quyền riêng tư của người khác',card('Tôn trọng',ul(['<b>Xin phép</b> trước khi chụp, quay, đăng ảnh người khác.','Không <b>tag, chia sẻ</b> thông tin riêng tư của bạn bè.','Không <b>theo dõi, thu thập</b> dữ liệu trái phép.'],6)),KEY('Quyền riêng tư hai chiều: bảo vệ thông tin của <b>mình</b> và tôn trọng thông tin của <b>người khác</b>.')+OK('Tình huống: bạn muốn đăng ảnh nhóm → hỏi từng người trước.')))
