S.append(TB(c,B+' · 3','Các loại giấy phép phần mềm',['Loại','Đặc điểm','Ví dụ'],[['<b>Thương mại</b> (bản quyền)','trả tiền, không được sao chép, sửa đổi','Microsoft Office'],['<b>Miễn phí</b> (freeware)','dùng miễn phí, không có mã nguồn','nhiều ứng dụng tải về'],['<b>Dùng thử</b> (shareware)','dùng thử có hạn, sau đó phải mua','phần mềm dùng thử'],['<b>Mã nguồn mở</b>','được xem, sửa, chia sẻ theo giấy phép','Linux, Firefox, Python']],note=WARN('<b>Miễn phí ≠ mã nguồn mở</b>: phần mềm miễn phí có thể không công khai mã nguồn.')))
S.append(TB(c,B+' · 3','Giấy phép Creative Commons (CC)',['Kí hiệu','Ý nghĩa'],[['<b>BY</b> (Attribution)','phải <b>ghi nguồn</b> tác giả'],['<b>NC</b> (NonCommercial)','<b>không</b> dùng vì mục đích thương mại'],['<b>ND</b> (NoDerivatives)','<b>không</b> sửa đổi, chuyển thể'],['<b>SA</b> (ShareAlike)','sản phẩm mới <b>cùng giấy phép</b>'],['<b>CC0</b>','miễn mọi hạn chế (như miền công cộng)']],note=KEY('Ví dụ: <b>CC BY-NC</b> = được dùng, phải ghi nguồn, <b>không</b> dùng thương mại.')))
S.append(S2(c,B+' · 3','Cách sử dụng tài nguyên đúng bản quyền',card('Quy trình',ul(['1. Xem <b>giấy phép</b> của tác phẩm.','2. Dùng đúng <b>phạm vi cho phép</b> (có được sửa, dùng thương mại?).','3. <b>Ghi nguồn</b> theo yêu cầu: tác giả, tên, liên kết, giấy phép.','4. Không rõ → <b>xin phép</b> hoặc dùng nguồn khác.'],6)),KEY('Nguồn ảnh, nhạc miễn phí: các kho có giấy phép rõ ràng (ví dụ Wikimedia Commons, Unsplash, Pixabay).')))
